), normalized_catalogue AS (
  SELECT DISTINCT legacy_path,
    lower(regexp_replace(translate(trim(subject_name), 'ÀÁÂÃÄÅàáâãäåÇçÈÉÊËèéêëÌÍÎÏìíîïÑñÒÓÔÕÖòóôõöÙÚÛÜùúûüÝŸýÿ', 'AAAAAAaaaaaaCcEEEEeeeeIIIIiiiiNnOOOOOoooooUUUUuuuuYYyy'), '[^a-z0-9]+', '', 'g')) AS normalized_name
  FROM catalogue
), matches AS (
  SELECT DISTINCT n.id AS node_id, s.id AS subject_id
  FROM normalized_catalogue c
  JOIN public.aurore_pedagogical_nodes n ON n.legacy_path = c.legacy_path AND n.active = true
  JOIN public.aurore_pedagogical_subjects s
    ON s.active = true
   AND lower(regexp_replace(translate(trim(s.name), 'ÀÁÂÃÄÅàáâãäåÇçÈÉÊËèéêëÌÍÎÏìíîïÑñÒÓÔÕÖòóôõöÙÚÛÜùúûüÝŸýÿ', 'AAAAAAaaaaaaCcEEEEeeeeIIIIiiiiNnOOOOOoooooUUUUuuuuYYyy'), '[^a-z0-9]+', '', 'g')) = c.normalized_name
)
INSERT INTO public.aurore_pedagogical_node_subjects (node_id, subject_id, sort_order)
SELECT m.node_id, m.subject_id, 0
FROM matches m
ON CONFLICT (node_id, subject_id) DO NOTHING;
